dashboard.definition:
{
	"title": "Policy Management",
	"description": "Monitor access-policy coverage, change, and exceptions needing review.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Zero Trust Access",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/zero-trust-access.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Policy Management\nMonitor access-policy coverage, change, and exceptions needing review."
			}
		},
		"viz_secure_networking_zta_duo_auth_outcomes_by_application": {
			"type": "splunk.table",
			"title": "ZTA Duo Authentication Outcomes by Application",
			"dataSources": {
				"primary": "ds_secure_networking_zta_duo_auth_outcomes_by_application"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Summarizes end-user Cisco Duo MFA decisions by protected application and factor, including successes, denials, fraud reports, affected users, and failure rate."
		},
		"viz_secure_networking_infra_duo_blocked_posture_identity": {
			"type": "splunk.table",
			"title": "Duo Blocked Posture and Identity Events",
			"dataSources": {
				"primary": "ds_secure_networking_infra_duo_blocked_posture_identity"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Combines Duo denied identity decisions with current endpoint posture failures such as missing encryption, firewall, password, or trust controls."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Identity-security and access-policy owners  •  **Sources:** Cisco Duo authentication, identity, and endpoint-posture telemetry  •  **Reading guide:** Review decisions by application, then investigate denied identities and posture gaps.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Policy outcomes\nReview decisions by application, then investigate denied identities and posture gaps."
			}
		}
	},
	"dataSources": {
		"ds_secure_networking_zta_duo_auth_outcomes_by_application": {
			"name": "Secure Networking - ZTA Duo Authentication Outcomes by Application",
			"options": {
				"ref": "secure_networking_zta_duo_auth_outcomes_by_application",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_secure_networking_infra_duo_blocked_posture_identity": {
			"name": "Secure Networking - Duo Blocked Posture and Identity Events",
			"options": {
				"ref": "secure_networking_infra_duo_blocked_posture_identity",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 640,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 88
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 14,
							"w": 56,
							"h": 56
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 108,
							"y": 4,
							"w": 1292,
							"h": 76
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 100,
							"w": 1400,
							"h": 64
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 176,
							"w": 1400,
							"h": 54
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_zta_duo_auth_outcomes_by_application",
						"position": {
							"x": 20,
							"y": 242,
							"w": 690,
							"h": 300
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_infra_duo_blocked_posture_identity",
						"position": {
							"x": 730,
							"y": 242,
							"w": 690,
							"h": 300
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
